                            '368991000119100',
                            '301011002',
                            '16916631000119104',
                            '369001000119100',
                            '369011000119102',
                            '369021000119100',
                            '369031000119107',
                            '16690001000004101',
                            '43025002')

    AND med_2.SuppliedCode IN ('1000811000001108',
